<?php header('Content-Type: application/json; charset=utf-8');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'error'=>'POST required']);exit;}$input=json_decode(file_get_contents('php://input'),true);if(!is_array($input)){http_response_code(400);echo json_encode(['ok'=>false,'error'=>'Invalid JSON']);exit;}$type=$input['type']??'personal';if(!in_array($type,['personal','business'],true)){http_response_code(400);echo json_encode(['ok'=>false,'error'=>'Invalid account type']);exit;}if($type==='business'){if(empty($input['domain'])||empty($input['username'])){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'Business domain and username are required']);exit;}$domain=strtolower(trim($input['domain']));$username=strtolower(trim($input['username']));if(!preg_match('/^[a-z0-9-]+\\.[a-z]{2,}(?:\\.[a-z]{2,})?$/',$domain)||!preg_match('/^[a-z0-9][a-z0-9._-]{0,63}$/',$username)){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'Invalid business address']);exit;}$address=$username.'.'.$domain;}else{$address=$input['email']??'';}echo json_encode(['ok'=>true,'accountType'=>$type,'address'=>$address,'message'=>'Authentication endpoint is ready for a database/session implementation.']);?>